    "go/types"
    "io"
    "os"
    "os/exec"
    "path/filepath"
    "regexp"
    "sort"
    "strings"
)

type multiFlag []string

func (m *multiFlag) String() string { return strings.Join(*m, " ") }
func (m *multiFlag) Set(s string) error { *m = append(*m, s); return nil }

type options struct {
    tags multiFlag
    asserts bool
    blank bool
    abspath bool
    excludePath string
    excludeOnly bool
    ignores multiFlag
    ignorePkg string
    ignoreTests bool
    ignoreGenerated bool
    mod string
    verbose bool
}

type pkgError struct {
    ImportStack []string
    Pos string
    Err string
}

type goPackage struct {
    Dir string
    ImportPath string
    Name string
    Match []string
    Standard bool
    Export string
    GoFiles []string
    TestGoFiles []string
    XTestGoFiles []string
    Error *pkgError
    DepsErrors []pkgError
}

type excludeRule struct {
    name string
    firstArg string
}

type ignoreRule struct {
    pkg string
    re *regexp.Regexp
}

type report struct {
    file string
    line int
    col int
    funcName string
    text string
    order int
}

type checker struct {
    opts options
    excludes []excludeRule
    ignoreRules []ignoreRule
    ignorePkgs map[string]bool
    fset *token.FileSet
    info *types.Info
    cwd string
    lineCache map[string][]string
    reports []report
    order int
}

var errorType = types.Universe.Lookup("error").Type()
var generatedRE = regexp.MustCompile(`(?m)^// Code generated .* DO NOT EDIT\.$`)

func main() {
    var opts options
    flag.Var(&opts.tags, "tags", "comma or space-separated list of build tags to include")
    flag.BoolVar(&opts.asserts, "asserts", false, "if true, check for ignored type assertion results")
    flag.BoolVar(&opts.blank, "blank", false, "if true, check for errors assigned to blank identifier")
    flag.BoolVar(&opts.abspath, "abspath", false, "print absolute paths to files")
    flag.StringVar(&opts.excludePath, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
    flag.BoolVar(&opts.excludeOnly, "excludeonly", false, "Use only excludes from -exclude file")
    flag.Var(&opts.ignores, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
    flag.StringVar(&opts.ignorePkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
    flag.BoolVar(&opts.ignoreTests, "ignoretests", false, "if true, checking of _test.go files is disabled")
    flag.BoolVar(&opts.ignoreGenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
    flag.StringVar(&opts.mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
    flag.BoolVar(&opts.verbose, "verbose", false, "produce more verbose logging")
    flag.Parse()

    excludes, err := readExcludes(opts.excludePath)
    if err != nil {
        fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
        os.Exit(2)
    }
    ignoreRules, ignorePkgs := parseIgnores(opts.ignores, opts.ignorePkg)

    args := flag.Args()
    if len(args) == 0 {
        args = []string{"."}
    }
    for i, a := range args {
        if a == "all" {
            args[i] = "..."
        }
    }

