            fmt.Fprintf(os.Stderr, "checking %s\n", gp.ImportPath)
        }
        c := &checker{opts: opts, excludes: excludes, ignoreRules: ignoreRules, ignorePkgs: ignorePkgs, cwd: cwd, lineCache: map[string][]string{}}
        c.checkPackage(gp, exports, false)
        if !opts.ignoreTests && len(gp.XTestGoFiles) > 0 {
            c.checkPackage(gp, exports, true)
        }
        c.sortReports()
        for _, r := range c.reports {
            anyReports = true
            if opts.verbose && r.funcName != "" {
                fmt.Printf("%s:%d:%d:\t%s\t%s\n", r.file, r.line, r.col, r.funcName, r.text)
            } else {
                fmt.Printf("%s:%d:%d:\t%s\n", r.file, r.line, r.col, r.text)
            }
        }
    }
    if anyReports {
        os.Exit(1)
    }
}

func readExcludes(path string) ([]excludeRule, error) {
    if path == "" { return nil, nil }
    f, err := os.Open(path)
    if err != nil { return nil, err }
    defer f.Close()
    var rules []excludeRule
    sc := bufio.NewScanner(f)
    for sc.Scan() {
        line := strings.TrimSpace(sc.Text())
        if line == "" || strings.HasPrefix(line, "//") { continue }
        r := excludeRule{name: line}
        // A final parenthesized suffix after the final dot denotes a first-argument condition.
        lastDot := strings.LastIndex(line, ".")
        lastOpen := strings.LastIndex(line, "(")
        if strings.HasSuffix(line, ")") && lastOpen > lastDot {
            r.name = strings.TrimSpace(line[:lastOpen])
            r.firstArg = strings.TrimSpace(line[lastOpen+1:len(line)-1])
        }
        rules = append(rules, r)
    }
    return rules, sc.Err()
}

func parseIgnores(vals []string, pkgs string) ([]ignoreRule, map[string]bool) {
    var out []ignoreRule
    for _, v := range vals {
        for _, part := range strings.Split(v, ",") {
            part = strings.TrimSpace(part)
            if part == "" { continue }
            pkg := ""
            pat := part
            if i := strings.Index(part, ":"); i >= 0 {
                pkg, pat = part[:i], part[i+1:]
            }
            re, err := regexp.Compile(pat)
            if err == nil { out = append(out, ignoreRule{pkg: pkg, re: re}) }
        }
    }
    m := map[string]bool{}
    for _, p := range strings.Split(pkgs, ",") {
        p = strings.TrimSpace(p)
        if p != "" { m[p] = true }
    }
    return out, m
}

func loadPackages(args []string, opts options) ([]goPackage, map[string]string, error) {
    // go/packages treats an empty plain directory as no packages. Avoid a noisy go command in that common case.
    if len(args) == 1 && args[0] == "." && !hasAnyGoFile(".") && findGoMod(".") == "" {
        return nil, map[string]string{}, nil
    }
    cmdArgs := []string{"list", "-json", "-e", "-deps", "-export"}
    if !opts.ignoreTests { cmdArgs = append(cmdArgs, "-test") }
    if len(opts.tags) > 0 {
        cmdArgs = append(cmdArgs, "-tags", strings.Join(opts.tags, " "))
    }
    if opts.mod != "" { cmdArgs = append(cmdArgs, "-mod", opts.mod) }
    cmdArgs = append(cmdArgs, args...)
    cmd := exec.Command("go", cmdArgs...)
    var stdout, stderr bytes.Buffer
    cmd.Stdout = &stdout
    cmd.Stderr = &stderr
    err := cmd.Run()
    if err != nil {
        st := strings.TrimRight(stderr.String(), "\n")
        if st != "" {
            return nil, nil, fmt.Errorf("err: %v: stderr: %s", err, st+"\n")
        }
        return nil, nil, fmt.Errorf("err: %v", err)
    }
    dec := json.NewDecoder(&stdout)
    var pkgs []goPackage
    exports := map[string]string{}
    for {
        var p goPackage
        if err := dec.Decode(&p); err != nil {
            if err == io.EOF { break }
            return nil, nil, err
        }
        if p.Export != "" { exports[p.ImportPath] = p.Export }
        pkgs = append(pkgs, p)
    }
    return pkgs, exports, nil
}

func hasAnyGoFile(dir string) bool {
    entries, err := os.ReadDir(dir)
    if err != nil { return false }
    for _, e := range entries {
        if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") { return true }
    }
    return false
}

func findGoMod(dir string) string {
    abs, err := filepath.Abs(dir)
    if err != nil { return "" }
    for {
        p := filepath.Join(abs, "go.mod")
        if _, err := os.Stat(p); err == nil { return p }
        parent := filepath.Dir(abs)
        if parent == abs { return "" }
        abs = parent
    }
}

func firstPackageError(pkgs []goPackage, ignoreTests bool) string {
    for _, p := range pkgs {
        if p.Error != nil {
            if strings.Contains(p.Error.Err, "no Go files") { continue }
            if ignoreTests && (strings.HasSuffix(p.ImportPath, ".test") || strings.Contains(p.ImportPath, " [")) { continue }
            return fmt.Sprintf("errors while loading package %s: [-: %s]", p.ImportPath, p.Error.Err)
        }
        if len(p.DepsErrors) > 0 {
            e := p.DepsErrors[0]
            return fmt.Sprintf("errors while loading package %s: [-: %s]", p.ImportPath, e.Err)
        }
    }
    return ""
}

func (c *checker) checkPackage(gp goPackage, exports map[string]string, xtest bool) {
    c.fset = token.NewFileSet()
    c.info = &types.Info{
        Types: map[ast.Expr]types.TypeAndValue{},
        Uses: map[*ast.Ident]types.Object{},
        Selections: map[*ast.SelectorExpr]*types.Selection{},
    }
    files := []*ast.File{}
    names := []string{}
    if xtest {
        names = append(names, gp.XTestGoFiles...)
    } else {
        names = append(names, gp.GoFiles...)
        if !c.opts.ignoreTests { names = append(names, gp.TestGoFiles...) }
    }
    for _, name := range names {
        path := name
        if !filepath.IsAbs(path) { path = filepath.Join(gp.Dir, name) }
        if c.opts.ignoreGenerated && isGenerated(path) { continue }
        f, err := parser.ParseFile(c.fset, path, nil, parser.ParseComments)
        if err == nil { files = append(files, f) }
    }
    if len(files) == 0 { return }
    imp := importer.ForCompiler(c.fset, "gc", func(path string) (io.ReadCloser, error) {
        if p := exports[path]; p != "" { return os.Open(p) }
        return nil, fmt.Errorf("no export data for %s", path)
    })
    conf := types.Config{Importer: imp, Error: func(error) {}}
    importPath := gp.ImportPath
    if xtest { importPath += "_test" }
    _, _ = conf.Check(importPath, c.fset, files, c.info)
    for _, f := range files { c.walkFile(f) }
}

func isGenerated(path string) bool {
    b, err := os.ReadFile(path)
    if err != nil { return false }
    s := string(b)
    if i := strings.Index(s, "\npackage "); i >= 0 { s = s[:i] }
    return generatedRE.MatchString(s)
}

func (c *checker) walkFile(f *ast.File) {
    commaOK := map[*ast.TypeAssertExpr]bool{}
    ast.Inspect(f, func(n ast.Node) bool {
        switch x := n.(type) {
        case *ast.AssignStmt:
            c.handleAssign(x, commaOK)
        case *ast.ValueSpec:
            c.handleValueSpec(x, commaOK)
        case *ast.ExprStmt:
            if call, ok := x.X.(*ast.CallExpr); ok { c.reportCallIfUnchecked(call) }
        case *ast.GoStmt:
            if x.Call != nil { c.reportCallIfUnchecked(x.Call) }
        case *ast.DeferStmt:
            if x.Call != nil { c.reportCallIfUnchecked(x.Call) }
        }
        return true
    })
    if c.opts.asserts {
        ast.Inspect(f, func(n ast.Node) bool {
            ta, ok := n.(*ast.TypeAssertExpr)
            if !ok { return true }
            if commaOK[ta] { return true }
            c.addReport(ta.X.Pos(), "", nil)
            return true
        })
    }
}

func (c *checker) handleAssign(a *ast.AssignStmt, commaOK map[*ast.TypeAssertExpr]bool) {
    if len(a.Rhs) == 1 {
        if ta, ok := a.Rhs[0].(*ast.TypeAssertExpr); ok && len(a.Lhs) == 2 {
            commaOK[ta] = true
            if c.opts.asserts && c.opts.blank {
                if id, ok := a.Lhs[1].(*ast.Ident); ok && id.Name == "_" { c.addReport(id.Pos(), "", nil) }
            }
            return
        }
        if call, ok := a.Rhs[0].(*ast.CallExpr); ok {
            c.handleAssignmentCall(a.Lhs, call)
            return
        }
    }
    if len(a.Rhs) == len(a.Lhs) {
        for i, rhs := range a.Rhs {
            if call, ok := rhs.(*ast.CallExpr); ok { c.handleSingleAssignment(a.Lhs[i], call) }
        }
    }
}

func (c *checker) handleValueSpec(v *ast.ValueSpec, commaOK map[*ast.TypeAssertExpr]bool) {
    lhs := make([]ast.Expr, len(v.Names))
    for i, n := range v.Names { lhs[i] = n }
    if len(v.Values) == 1 {
        if ta, ok := v.Values[0].(*ast.TypeAssertExpr); ok && len(lhs) == 2 {
            commaOK[ta] = true
            if c.opts.asserts && c.opts.blank {
                if id, ok := lhs[1].(*ast.Ident); ok && id.Name == "_" { c.addReport(id.Pos(), "", nil) }
            }
            return
        }
        if call, ok := v.Values[0].(*ast.CallExpr); ok { c.handleAssignmentCall(lhs, call); return }
    }
    if len(v.Values) == len(lhs) {
        for i, rhs := range v.Values {
            if call, ok := rhs.(*ast.CallExpr); ok { c.handleSingleAssignment(lhs[i], call) }
        }
    }
}

func (c *checker) handleAssignmentCall(lhs []ast.Expr, call *ast.CallExpr) {
    if c.callExcluded(call) { return }
    res := c.resultTypes(call)
    for i, t := range res {
        if i >= len(lhs) { break }
        if isError(t) && c.opts.blank {
            if id, ok := lhs[i].(*ast.Ident); ok && id.Name == "_" { c.addReport(id.Pos(), c.verboseName(call), call) }
        }
    }
}

func (c *checker) handleSingleAssignment(lhs ast.Expr, call *ast.CallExpr) {
    if c.callExcluded(call) { return }
    res := c.resultTypes(call)
    if len(res) != 1 { return }
    if isError(res[0]) && c.opts.blank {
        if id, ok := lhs.(*ast.Ident); ok && id.Name == "_" { c.addReport(id.Pos(), c.verboseName(call), call) }
    }
}

func (c *checker) reportCallIfUnchecked(call *ast.CallExpr) {
    if c.callExcluded(call) { return }
    for _, t := range c.resultTypes(call) {
        if isError(t) { c.addReport(call.Lparen, c.verboseName(call), call); return }
    }
}

func (c *checker) resultTypes(call *ast.CallExpr) []types.Type {
    tv, ok := c.info.Types[call]
    if !ok || tv.Type == nil { return nil }
    if tup, ok := tv.Type.(*types.Tuple); ok {
        out := make([]types.Type, tup.Len())
        for i := 0; i < tup.Len(); i++ { out[i] = tup.At(i).Type() }
        return out
    }
    return []types.Type{tv.Type}
}

func isError(t types.Type) bool {
    if t == nil { return false }
    if types.Identical(t, errorType) || types.AssignableTo(t, errorType) { return true }
    iface, _ := errorType.Underlying().(*types.Interface)
    return iface != nil && types.Implements(t, iface)
}

func (c *checker) callExcluded(call *ast.CallExpr) bool {
    name := c.fullName(call)
    if name == "" { return false }
    pkg, short := splitFuncName(name)
    if c.ignorePkgs[pkg] { return true }
    for _, r := range c.ignoreRules {
        if r.pkg != "" && r.pkg != pkg { continue }
        if r.re.MatchString(short) || r.re.MatchString(name) { return true }
    }
    for _, r := range c.excludes {
        if r.name != name { continue }
        if r.firstArg == "" || c.firstArgMatches(call, r.firstArg) { return true }
    }
    if !c.opts.excludeOnly && c.builtinExcluded(call, name) { return true }
    return false
}

func (c *checker) builtinExcluded(call *ast.CallExpr, name string) bool {
    switch name {
    case "fmt.Print", "fmt.Printf", "fmt.Println":
        return true
    case "fmt.Fprint", "fmt.Fprintf", "fmt.Fprintln":
        if len(call.Args) == 0 { return false }
        if isSelectorName(call.Args[0], "os", "Stderr") { return true }
        // Writes to in-memory buffers/builders are conventionally infallible.
        at := c.exprTypeString(call.Args[0])
        if at == "*bytes.Buffer" || at == "bytes.Buffer" || at == "*strings.Builder" || at == "strings.Builder" {
            return true
        }
    case "(*bytes.Buffer).Write", "(*bytes.Buffer).WriteString":
        return true
    case "(*strings.Builder).Write", "(*strings.Builder).WriteString":
        return true
    }
    return false
}

func (c *checker) firstArgMatches(call *ast.CallExpr, cond string) bool {
    if len(call.Args) == 0 { return false }
    if cond == "os.Stdout" { return isSelectorName(call.Args[0], "os", "Stdout") }
    if cond == "os.Stderr" { return isSelectorName(call.Args[0], "os", "Stderr") }
    return c.exprTypeString(call.Args[0]) == cond
}

func isSelectorName(e ast.Expr, pkg, name string) bool {
    sel, ok := e.(*ast.SelectorExpr)
    if !ok || sel.Sel.Name != name { return false }
    id, ok := sel.X.(*ast.Ident)
    return ok && id.Name == pkg
}

func (c *checker) exprTypeString(e ast.Expr) string {
    if tv, ok := c.info.Types[e]; ok && tv.Type != nil { return types.TypeString(tv.Type, qualifier) }
    return ""
}

func qualifier(p *types.Package) string {
    if p == nil { return "" }
    return p.Path()
}

func (c *checker) fullName(call *ast.CallExpr) string {
    switch f := call.Fun.(type) {
    case *ast.SelectorExpr:
        if sel := c.info.Selections[f]; sel != nil {
            if fn, ok := sel.Obj().(*types.Func); ok { return fullFuncName(fn) }
        }
        if obj, ok := c.info.Uses[f.Sel].(*types.Func); ok { return fullFuncName(obj) }
    case *ast.Ident:
        if obj, ok := c.info.Uses[f].(*types.Func); ok { return fullFuncName(obj) }
    }
    return ""
}

func (c *checker) verboseName(call *ast.CallExpr) string {
    if _, ok := call.Fun.(*ast.SelectorExpr); !ok { return "" }
    return c.fullName(call)
}

func fullFuncName(fn *types.Func) string {
    if fn == nil { return "" }
    sig, _ := fn.Type().(*types.Signature)
    if sig != nil && sig.Recv() != nil {
        return "(" + types.TypeString(sig.Recv().Type(), qualifier) + ")." + fn.Name()
    }
    if fn.Pkg() == nil { return fn.Name() }
    return fn.Pkg().Path() + "." + fn.Name()
}

func splitFuncName(name string) (pkg, short string) {
    short = name
    if strings.HasPrefix(name, "(") {
        if i := strings.LastIndex(name, ")."); i >= 0 {
            recv := strings.TrimPrefix(name[:i+1], "(")
            recv = strings.TrimSuffix(recv, ")")
            recv = strings.TrimPrefix(recv, "*")
            if j := strings.LastIndex(recv, "."); j >= 0 { pkg = recv[:j] }
            short = name[i+2:]
            return
        }
    }
    if i := strings.LastIndex(name, "."); i >= 0 { pkg, short = name[:i], name[i+1:] }
    return
}

func (c *checker) addReport(pos token.Pos, funcName string, call *ast.CallExpr) {
    if !pos.IsValid() { return }
    p := c.fset.Position(pos)
    path := p.Filename
    outPath := path
    if c.opts.abspath {
        if abs, err := filepath.Abs(path); err == nil { outPath = abs }
    } else {
        if rel, err := filepath.Rel(c.cwd, path); err == nil { outPath = rel }
    }
    outPath = filepath.ToSlash(outPath)
    c.order++
    c.reports = append(c.reports, report{file: outPath, line: p.Line, col: p.Column, funcName: funcName, text: c.sourceLine(path, p.Line), order: c.order})
}

func (c *checker) sourceLine(path string, line int) string {
    lines, ok := c.lineCache[path]
    if !ok {
        b, err := os.ReadFile(path)
        if err != nil { return "" }
        lines = strings.Split(string(b), "\n")
        c.lineCache[path] = lines
    }
    if line <= 0 || line > len(lines) { return "" }
    return strings.TrimSpace(lines[line-1])
}

func (c *checker) sortReports() {
    sort.SliceStable(c.reports, func(i, j int) bool {
        a, b := c.reports[i], c.reports[j]
        if a.file != b.file { return a.file < b.file }
        if a.line != b.line { return a.line < b.line }
        if a.col != b.col { return a.col < b.col }
        return a.order < b.order
    })
}
